import { IPriceCalculator, IPriceCalculatorData, IPriceCalculatorTooltipData } from "@/api/type";
import { defaultPriceCalcData, defaultPriceSettingsData, defaultPriceSettingsTooltipData } from "@/api/default";
import { request } from "@/utils/request";
import { tippy } from "vue-tippy";


@Component({
  components: {
    tippy
  }
})

export default class App extends Vue  {
  private calcData: IPriceCalculatorData = defaultPriceCalcData
  private data: IPriceCalculator = defaultPriceSettingsData
  private exteriorTableMap: string[] = ['Full3D', 'bird-eye', 'Photomontage', 'VR360']
  private interiorTableMap: string[] = ['View', 'VR360']
  private promocode = ""
  private coefficientData: any
  private valuteSelect = 0
  private precentPromocode = 0
  private priceStr: IPriceCalculatorTooltipData = defaultPriceSettingsTooltipData

  created() {
    this.calcData = (window as any).calcData
    this.coefficientData = (window as any).coefficientData
    this.priceStr = (window as any).priceStr
  }

  private static priceSet(data: any) {
    const price = Number.prototype.toFixed.call(parseFloat(data) || 0, 2)
    return price.replace(/(\D)/g, ".").replace(/(\d)(?=(\d{3})+(?!\d))/g, "$1 ");
  };

  private caclulatePrice() {
    let result = 0;

    if(this.data.exterior.table.length > 0) {
      const ex = this.data.exterior
      const cex = this.calcData.exteriorData
      for(const item of ex.table) {
        const price = cex.table[item.type]
        result += price.base + price.size[item.size] + price.timeOfDay[item.timeOfDay] + price.season[item.season]

        result += cex.style[ex.style]
        result += cex.typeOfBuildings[ex.typeOfBuilding]
        result += cex.interiors[ex.interior]
        result += cex.environment[ex.environment]
        if(!(item.type === 3 && ex.people === 1))
          result += cex.people[ex.people]
      }

      result += cex.buildingPrice * (ex.buildingCount - 1)
    }

    if(this.data.interior.table.length > 0) {
      const int = this.data.interior
      const cint = this.calcData.interiorData

      int.table[0].saneRoom = 1;

      for(const item of int.table) {
        const price = cint.table[item.type]
        result += price.base + price.size[item.size] + price.saneRoom[item.saneRoom]

        result += cint.style[int.style]
        if(item.type === 0)
          result += cint.typeOfInteriors[int.typeOfInterior]
        result += cint.libraryContent[int.libraryContent]
        if(!(item.type === 1 && item.saneRoom === 1) || !(item.type === 1 && int.people === 1))
          result += cint.people[int.people]
      }
    }

    if(this.valuteSelect === 1)
      result *= this.coefficientData.EUR
    if(this.valuteSelect === 2)
      result *= this.coefficientData.GBP

    if(this.precentPromocode > 0)
      result -= result * (this.precentPromocode / 100)

    return App.priceSet(result)
  }

  private promocodeUpdate() {
    request('post', '/promocode', { promocode: this.promocode }).then((e) => {
      if(e.ok) {
        this.precentPromocode = +e.data
      }
    })
  }
}
